from typing import List, Tuple

def determine_rank(N: int, M: int, constraints: List[Tuple[int, int, int]]) -> List[int]:
    G = [[] for _ in range(N)]
    for a, b, c in constraints:
        a -= 1
        b -= 1
        G[a].append((b, -c))
        G[b].append((a, c))

    used = [False for _ in range(N)]
    cost = [0 for _ in range(N)]

    def dfs(u, d):
        res = [u]
        used[u] = True
        cost[u] = d
        for v, c in G[u]:
            if used[v]: continue
            res += dfs(v, d + c)
        return res

    g = []
    st = []
    for i in range(N):
        if used[i]: continue
        comp = dfs(i, 0)
        m = min(cost[u] for u in comp)
        for u in comp:
            cost[u] -= m
        bit = 0
        for u in comp:
            bit |= (1 << cost[u])
        g.append(bit)
        st.append(comp)

    bitset = [[] for _ in range(N + 1)]
    for bit in range(1 << N):
        cnt = bin(bit).count('1')
        bitset[cnt].append(bit)

    ans = [-1] * N
    for i in range(len(g)):
        now = 0
        dp = [False] * (1 << N)
        dp[0] = True
        x = g[i]
        for j in range(len(g)):
            if i == j:
                continue
            for bit in bitset[now]:
                if not dp[bit]:
                    continue
                for sft in range(N):
                    if bit | (g[j] << sft) >= (1 << N):
                        break
                    dp[bit | (g[j] << sft)] = True
            now += bin(g[j]).count('1')

        ok = []
        for bit in bitset[N - bin(x).count('1')]:
            if not dp[bit]:
                continue
            for sft in range(N):
                if x << sft >= (1 << N):
                    break
                if bit ^ (x << sft) == (1 << N) - 1:
                    ok.append(sft)

        if len(ok) == 1:
            for s in st[i]:
                ans[s] = ok[0] + 1

    return ans
